"""Explain the unified model overview without mixing endpoints or evaluation units."""
import pandas as pd
from project_paths import project_root
ROOT=project_root();FIG=ROOT/'work/cumulative_signature';src=FIG/'source_data'
a=pd.read_csv(src/'all_models_formal_comparison.tsv',sep='\t');definitions=pd.read_csv(src/'all_model_definitions.tsv',sep='\t');training=pd.read_csv(src/'all_models_training_comparison.tsv',sep='\t')
assert len(a)==143 and len(definitions)==13 and len(training)==182
lines=['# 全部模型与消融：统一比较','','## 纳入范围','','总览纳入13种已完成配置×11个共同正式评价范围，共143项结果。不是新增训练143个模型：冻结迁移复用源模型，多个范围也可能共享细胞。旧固定K使用原数据集K；新累计归因使用已冻结源阈值，不在目标调参。','','|配置组|数量|输入与变化|','|---|---:|---|','|旧固定K完整图|4|15B、PPI、Qwen、650M图；16维可训练gene identity＋表达|','|累计归因完整图|4|同四图、同16维特征，节点数随细胞变化|','|旧固定K／累计归因无边|2|保留各自节点和特征，去掉全部输入边；各自是四图共享对照|','|随机signature＋15B图|1|既有随机选基因消融；保留原节点规模和实验设置|','|原生STATE SE＋MLP|1|2048维细胞向量，非蛋白节点图分类器|','|15B图＋ESM2-15B gene embedding|1|旧固定K，冻结5120维蛋白衍生gene向量＋表达|','','特别注意：15B graph表示边来自ESM2-15B表示空间，不代表节点输入是15B蛋白向量。只有最后一列15B gene emb使用冻结的5120维gene向量。Native SE为STATE细胞模型生成的细胞向量，也不是15B蛋白节点特征。','','总图展示正式已完成、能够在同一范围评价的配置。此前暂缓的Qwen/650M冻结蛋白gene向量完整实验不补成结果；历史试跑的部分组合也不与完整14项设计混用。', '',f'## [全部模型：共同正式评价范围]({(FIG/"figures/12_all_models_formal_comparison.pdf").as_posix()})','','同一张图上下两面板分别为AUROC和固定概率阈值0.5的balanced accuracy。横轴13个配置，纵轴11个同范围评价。颜色统一0–1，数值越高越好；0是合法指标，不是缺失。所有143格有实际结果。源表all_models_formal_comparison.tsv；模型的图、节点特征和选节点方法见all_model_definitions.tsv。','','PC9两折测试指标等权；ReSis按两个生物学重复指标等权；EOC先合并患者折外预测，再对患者平均细胞概率计算指标（11位患者）；外部EOC四源折先平均细胞概率，再平均患者内细胞（4位有标签患者）；其他迁移保留指定细胞系/药物范围全部合格有标签细胞。unknown不参与指标。AUROC/AP使用原正类方向，不翻转分数；不按不同模型各自挑选更有利细胞。','','该图用于比较同一行、同一终点的性能。不要跨不同疾病、药物、DTEP状态、杀伤命运和临床结局直接平均打榜。TS485T两个范围共享未处理细胞，不是两次完全独立验证。AUROC高但BA接近0.5应检查阈值与单类预测；患者数小的离散AUROC不能视为稳定优势。完整AP、MCC、macro-F1及Brier在源表中，Brier越低越好。','',f'## [全部模型：14项训练设计逐项结果]({(FIG/"figures/13_all_models_14_training_designs.pdf").as_posix()})','','同图上下为测试细胞AUROC和BA，14行原训练划分，不合并折。灰线区分前两项随机细胞划分与后12项分组外推；fold不是随机种子重复。EOC逐折是细胞指标，不能替代主图中患者级OOF。源表all_models_training_comparison.tsv；实际分组定义见fold_definitions.tsv。']
missing=training[training.result_status.ne('completed')]
if len(missing):
 lines+=['',f'逐项图有{len(missing)}格历史结果缺失，标NA，不补零也不借用其他模型；没有为补图追加随机signature训练：']
 for r in missing.itertuples():lines.append(f'- {r.dataset} / {r.fold} / {r.model_id}。')
lines+=['','## 当前总图最支持什么','']
for ds in ['GSE149383_PC9_DTEP_sample_grouped','GSE223003_carboplatin_pre','GSE223003_nk_pre','GSE223003_olaparib_pre']:
 part=a[a.dataset.eq(ds)];native=part[part.model_id.eq('native_se__mlp')].iloc[0];graphs=part[part.model_id.isin(definitions.iloc[:8].model_id)]
 lines.append(f'- {ds}：原生SE＋MLP AUROC {native.auroc:.3f}（BA {native.balanced_accuracy:.3f}），八种新旧完整图AUROC为{graphs.auroc.min():.3f}–{graphs.auroc.max():.3f}。本轮更复杂的图分类器并未超过该细胞表示对照。')
clinical=a[a.dataset.eq('GSE165897_pre_EOC')];external=a[a.dataset.eq('GSE154600_EPI_external')];native=clinical[clinical.model_id.eq('native_se__mlp')].iloc[0];protein=clinical[clinical.model_id.eq('fixed_k__state_graph__state_15b')].iloc[0]
lines+=['',f'EOC患者OOF中，原生SE＋MLP AUROC为{native.auroc:.3f}，冻结15B节点特征为{protein.auroc:.3f}；在4位外部患者中，两者分别为{external[external.model_id.eq("native_se__mlp")].iloc[0].auroc:.3f}和{external[external.model_id.eq("fixed_k__state_graph__state_15b")].iloc[0].auroc:.3f}。优势随队列反转，不能宣布某种表示普遍最好；外部4人结果尤其不稳定。','','TS485T新无边仍接近完整图，说明该背景中的强排序信号不依赖这些输入边才能出现。PC9的图相对无边有小幅优势，但仍未超过原生SE＋MLP。跨癌种迁移和临床结局结果限制了通用耐药预测的结论。','','## 怎样形成科研结论','','优先比较同节点政策下的完整图与共享无边：它们保持特征、节点、缩放、划分和训练预算一致，差异才对应有无跨基因消息传递。再比较新旧无边，判断选节点本身的影响；进一步看边优势的变化。ESM2-15B冻结向量与16维可训练ID改变了表示维数、冻结方式和投影参数，不能仅据分数归因于蛋白语义。SE＋MLP也同时改变了细胞表示和分类器。','','本轮是seed42单种子实验，不作显著性或普遍最优宣称。先看独立样本/患者与冻结迁移的绝对表现，再看相对差值；随机细胞划分接近满分不能证明患者泛化。低于随机排序的迁移不翻转方向，不据此解释为已识别耐药驱动gene。','','旧PC9宏表遗漏敏感类AP和阈值字段，本轮从保存的两折预测回算，并核对其他指标与原表一致；补充表为edge_ablation/fixedK_reference_metrics.tsv，原始历史表未修改。所有模型的图、特征及选节点方法由all_model_definitions.tsv明确区分。','',f'边贡献、新旧无边的逐范围分析见[边消融结果解读]({(FIG/"边消融结果解读.md").as_posix()})；环境及绝对CMD命令见[复现说明]({(FIG/"edge_ablation_exp.md").as_posix()})。']
(FIG/'全部模型对比解读.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print('Unified all-model interpretation written')
